'use strict';
let censusIndex=null,censusGeoIndex=null,censusSelected=null,censusProfile=null,censusRevision=0,censusMap=null,censusMapLayer=null;
const censusPromises=new Map();
const censusStateName=s=>STATE_NAMES[String(s)]||String(s||'');
const censusNumber=v=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString():'Unavailable';
function censusPct(value,denominator){return typeof value==='number'&&Number.isFinite(value)&&typeof denominator==='number'&&denominator>0?100*value/denominator:null;}
async function censusJSON(file){if(!censusPromises.has(file))censusPromises.set(file,(file.endsWith('.gz')?compressedJSON('data/demographics/'+file):fetch('data/demographics/'+file).then(r=>{if(!r.ok)throw Error('Census data could not load ('+r.status+').');return r.json();})).catch(e=>{censusPromises.delete(file);throw e;}));return censusPromises.get(file);}
function censusAreaList(){if(!censusIndex)return[];const type=$('profileType').value,state=$('profileState').value,q=$('profileSearch').value.trim().toLowerCase();return(censusIndex.geographies[type]||[]).filter(r=>(!state||String(r.state)===state)&&(!q||r.name.toLowerCase().includes(q)||r.code.includes(q)));}
function renderCensusChoices(){const type=$('profileType').value,rows=censusAreaList();$('profileChoices').innerHTML=rows.slice(0,30).map(r=>'<button class="area-choice '+(censusSelected?.type===type&&censusSelected?.code===r.code?'selected':'')+'" data-census-code="'+esc(r.code)+'">'+esc(r.name)+' <span class="help">'+esc(censusStateName(r.state))+' · '+esc(r.code)+'</span></button>').join('');$('profileChoiceStatus').textContent=rows.length?rows.length.toLocaleString()+' Census 2021 areas'+(rows.length>30?' · first 30 shown; search to narrow results.':'.'):'No Census 2021 areas match this search.';$('profileChoices').querySelectorAll('[data-census-code]').forEach(b=>b.onclick=()=>selectCensusArea(type,b.dataset.censusCode));}
async function selectCensusArea(type,code){if(!censusIndex)return;const row=(censusIndex.geographies[type]||[]).find(r=>r.code===code);if(!row)return;const revision=++censusRevision;censusSelected={...row,type};censusProfile=null;$('downloadProfileCSV').disabled=true;$('downloadProfileJSON').disabled=true;$('profileType').value=type;renderCensusChoices();$('profileStatus').textContent='Loading '+row.name+'…';$('profileStatus').classList.remove('error');$('profileOutput').hidden=true;try{const shard=await censusJSON(type==='SAL'?'SAL_'+String(row.state)+'.json.gz':'SA4.json.gz');if(revision!==censusRevision)return;const profile=shard[code];if(!profile)throw Error('This area has no published profile in this release.');censusProfile=profile;renderCensusProfile();$('profileStatus').textContent='Official ABS Census 2021 profile loaded.';renderCensusMap(revision);}catch(e){if(revision!==censusRevision)return;censusProfile=null;$('profileStatus').textContent=e.message;$('profileStatus').classList.add('error');$('profileOutput').hidden=true;}}
function renderCensusProfile(){const p=censusProfile;if(!p)return;$('profileOutput').hidden=false;$('downloadProfileCSV').disabled=false;$('downloadProfileJSON').disabled=false;$('censusName').textContent=p.name;$('censusIdentity').textContent=p.type+' '+p.code+' · '+censusStateName(p.state);$('censusPopulation').textContent=censusNumber(p.population);$('censusReference').textContent='2021 Census · ASGS Edition 3 / 2021 boundaries';$('profileMapCaption').textContent='Selected Census 2021 area. Display polygon simplified to 25 m.';renderCensusMetrics();renderCensusTable();}
function renderCensusMetrics(){const p=censusProfile;if(!p)return;const unit=$('profileUnit').value;$('metricGrid').innerHTML=p.metrics.map(m=>{const cats=m.categories||[],numeric=cats.filter(c=>typeof c.value==='number'&&Number.isFinite(c.value)),max=Math.max(1,...numeric.map(c=>c.value)),den=m.denominator;const many=cats.length>12;const rows=cats.map((c,i)=>{const pct=censusPct(c.value,den),available=typeof c.value==='number'&&Number.isFinite(c.value),display=unit==='percent'?(pct==null?'—':pct.toFixed(1)+'%'):censusNumber(c.value),width=unit==='percent'?(pct??0):available?100*c.value/max:0;return'<div class="chart-row '+(/not stated|not applicable|inadequately|other|unknown/i.test(c.label)?'unknown':'')+'" '+(many&&i>=12?'data-extra-row hidden':'')+' title="'+esc(c.label+': '+censusNumber(c.value)+(pct==null?'':' ('+pct.toFixed(2)+'%)'))+'"><span class="chart-label">'+esc(c.label)+'</span><div class="chart-track" aria-hidden="true"><div class="chart-fill" style="width:'+Math.min(100,Math.max(0,width))+'%"></div></div><span class="chart-value">'+esc(display)+'</span></div>';}).join('');return'<article class="metric-card" data-metric="'+esc(m.id)+'"><h3>'+esc(m.label)+'</h3><p class="metric-universe">'+esc(m.universe)+'<br>Denominator: '+esc(censusNumber(den))+' '+esc(m.unit||'')+'</p><div class="chart-bars" role="group" aria-label="'+esc(m.label+' distribution')+'">'+rows+'</div><div class="chart-axis"><span>0'+(unit==='percent'?'%':'')+'</span><span>'+(unit==='percent'?'100% of stated universe':esc(censusNumber(max))+' '+esc(m.unit||''))+'</span></div>'+(many?'<button class="metric-more">Show all '+cats.length+' categories</button>':'')+(m.partial_distribution?'<p class="quality-note">Partial measure: only the published Australian citizen count is shown. No non-citizen remainder is inferred.</p>':'')+((m.notes||[]).length?'<details class="quality-note"><summary>Definitions &amp; source notes</summary>'+m.notes.map(n=>'<p class="quality-note">'+esc(n)+'</p>').join('')+'</details>':'')+'<div class="source-caption">ABS Census 2021 · <a href="'+esc(m.source_url)+'" target="_blank" rel="noopener">'+esc(m.source_table)+' ↗</a><br>Published counts · '+esc(m.multiple_response?'Multiple responses allowed; shares are not mutually exclusive.':'Categories may differ slightly from totals due to Census perturbation.')+'</div></article>';}).join('');$('metricGrid').querySelectorAll('.metric-more').forEach(b=>b.onclick=()=>{const card=b.closest('.metric-card'),expanded=b.dataset.expanded==='true';card.querySelectorAll('[data-extra-row]').forEach(r=>r.hidden=expanded);b.dataset.expanded=String(!expanded);b.textContent=expanded?'Show all '+card.querySelectorAll('.chart-row').length+' categories':'Show fewer categories';});}
function censusExportRows(){if(!censusProfile)return[];const p=censusProfile;return p.metrics.flatMap(m=>(m.categories||[]).map(c=>({geography_type:p.type,geography_code:p.code,geography_name:p.name,state:censusStateName(p.state),census_year:p.year,boundary_year:p.boundary_year,metric:m.id,measure:m.label,category:c.label,count:c.value,unit:m.unit,denominator:m.denominator,universe:m.universe,percent:censusPct(c.value,m.denominator),multiple_response:m.multiple_response,source_table:m.source_table,source_field:c.source_field||'',source_url:m.source_url,notes:(m.notes||[]).join(' | '),matching_method:'Published Census 2021 value for selected 2021 area; no conversion to 2026 boundaries'})));}
function renderCensusTable(){const p=censusProfile;if(!p)return;$('censusTableBody').innerHTML=censusExportRows().map(r=>'<tr><td>'+esc(r.measure)+'</td><td>'+esc(r.category)+'</td><td>'+esc(censusNumber(r.count))+'</td><td>'+(r.percent==null?'—':r.percent.toFixed(2)+'%')+'</td><td>'+esc(censusNumber(r.denominator))+' '+esc(r.unit)+'<small>'+esc(r.universe)+'</small></td><td><a href="'+esc(r.source_url)+'" target="_blank" rel="noopener">'+esc(r.source_table)+' ↗</a><small>'+esc(r.source_field)+'</small></td></tr>').join('');$('censusTableCaption').textContent=p.name+' · '+p.type+' '+p.code+' · Census 2021 · published-area data';}
function censusSetView(view){$('metricGrid').hidden=view!=='graphs';$('censusTableWrap').hidden=view!=='table';$('profileGraphs').setAttribute('aria-pressed',String(view==='graphs'));$('profileTable').setAttribute('aria-pressed',String(view==='table'));}
async function renderCensusMap(revision=censusRevision){const p=censusProfile;if(!p||!$('page-profiles').classList.contains('active'))return;try{if(!censusGeoIndex)censusGeoIndex=await censusJSON('geo-index.json.gz');if(revision!==censusRevision)return;const area=censusGeoIndex[p.type]?.[p.code];if(!area?.bbox){$('profileMapCaption').textContent='No spatial boundary is available for this Census area.';if(censusMapLayer)censusMapLayer.clearLayers();return;}if(!censusMap){censusMap=L.map('profileMap',{preferCanvas:true,scrollWheelZoom:false,attributionControl:true}).setView([area.lat,area.lon],8);censusMap.attributionControl.addAttribution('ABS Census geography 2021');censusMapLayer=L.geoJSON(null,{style:censusMapStyle}).addTo(censusMap);}const fc=await censusJSON('geo/'+(p.type==='SAL'?'SAL_'+p.state:'SA4')+'.json.gz');if(revision!==censusRevision)return;const f=fc.features.find(f=>f.properties.c===p.code);censusMapLayer.clearLayers();if(f)censusMapLayer.addData(f);censusMap.invalidateSize();censusMap.fitBounds([[area.bbox[1],area.bbox[0]],[area.bbox[3],area.bbox[2]]],{padding:[15,15],maxZoom:13});}catch(e){if(revision===censusRevision)$('profileMapCaption').textContent='Profile values are available; boundary preview could not load. Select the area again to retry.';}}
function censusMapStyle(){const style=getComputedStyle(document.documentElement);return{color:style.getPropertyValue('--chart-accent').trim()||'#328b88',fillColor:style.getPropertyValue('--chart-accent').trim()||'#328b88',weight:2,fillOpacity:.18};}
function openCensusCandidates(type,name,state){showPage('profiles');$('profileType').value=type==='SA4'?'SA4':'SAL';$('profileState').value=String(state||'');$('profileSearch').value=name||'';renderCensusChoices();$('profileStatus').textContent='Choose the Census 2021 area below. Atlas 2026 areas and Census 2021 areas are separate definitions.';$('profileSearch').focus();}
document.addEventListener('locus:theme',()=>{if(censusMapLayer)censusMapLayer.setStyle(censusMapStyle);});
document.addEventListener('locus:page',e=>{if(e.detail==='profiles')setTimeout(()=>renderCensusMap(),40);});
$('profileSearch').oninput=renderCensusChoices;$('profileState').onchange=renderCensusChoices;$('profileType').onchange=()=>{$('profileSearch').value='';renderCensusChoices();};$('profileUnit').onchange=renderCensusMetrics;$('profileGraphs').onclick=()=>censusSetView('graphs');$('profileTable').onclick=()=>censusSetView('table');$('downloadProfileCSV').onclick=()=>{if(censusProfile)exportCSV(censusExportRows(),'Locus_'+censusProfile.type+'_'+censusProfile.code+'_Census2021.csv');};$('downloadProfileJSON').onclick=()=>{if(censusProfile)saveBlob(new Blob([JSON.stringify(censusProfile,null,2)],{type:'application/json'}),'Locus_'+censusProfile.type+'_'+censusProfile.code+'_Census2021.json');};
$('openAreaProfiles').onclick=()=>{const type=$('geogType').value,value=$('geogValue').value;openCensusCandidates(type,value?geoName(type,value):$('search').value,$('state').value);};
document.addEventListener('click',e=>{const b=e.target.closest('[data-census-search]');if(b)openCensusCandidates(b.dataset.censusType,b.dataset.censusSearch,b.dataset.censusState);});
async function startCensus(){try{censusIndex=await censusJSON('index.json');for(const[c,n]of Object.entries(STATE_NAMES))$('profileState').add(new Option(n,c));renderCensusChoices();$('profileCoverage').textContent=(censusIndex.geographies.SAL?.length||0).toLocaleString()+' locality records · '+(censusIndex.geographies.SA4?.length||0)+' SA4 records · Census 2021 · special nonspatial records retained';const pilot=censusIndex.geographies.SAL.find(r=>r.name==='Newtown (NSW)'&&String(r.state)==='1')||censusIndex.geographies.SAL.find(r=>r.name.toLowerCase()==='newtown'&&String(r.state)==='1')||censusIndex.geographies.SAL[0];if(pilot)selectCensusArea('SAL',pilot.code);}catch(e){$('profileStatus').textContent='Demographic index could not load: '+e.message;$('profileStatus').classList.add('error');$('profileRetry').hidden=false;}}
$('profileRetry').onclick=()=>{$('profileRetry').hidden=true;startCensus();};startCensus();
